effect.shader:
float valorDoMatte(vec4 m) {
    if (matteChannel == 0) return m.a;

    vec3 c = premultiplyMatte ? m.rgb * m.a : m.rgb;

    if (matteChannel == 1) return dot(c, vec3(0.299, 0.587, 0.114));
    if (matteChannel == 2) return c.r;
    if (matteChannel == 3) return c.g;
    if (matteChannel == 4) return c.b;

    float maior = max(max(c.r, c.g), c.b);
    float menor = min(min(c.r, c.g), c.b);
    float luz = (maior + menor) * 0.5;
    if (matteChannel == 5) return luz;

    float croma = maior - menor;
    if (matteChannel == 6) {
        // Saturação do HSL: zero no cinza, e a mesma fórmula nos dois lados
        // do meio, para branco e preto puros não dividirem por zero.
        if (croma <= 0.0) return 0.0;
        return croma / max(1.0 - abs(2.0 * luz - 1.0), 1e-4);
    }

    // Matiz, de 0 a 1 dando a volta no círculo de cor.
    if (croma <= 0.0) return 0.0;
    float h;
    if (maior == c.r) h = mod((c.g - c.b) / croma, 6.0);
    else if (maior == c.g) h = (c.b - c.r) / croma + 2.0;
    else h = (c.r - c.g) / croma + 4.0;
    return h / 6.0;
}

void main() {
    vec4 camada = texture(inputImg, acScreenNorm);
    float matte = clamp(valorDoMatte(texture(matteImg, acScreenNorm)), 0.0, 1.0);
    if (invertMatte) matte = 1.0 - matte;

    float alfa = combineWithOriginal ? camada.a * matte : matte;
    fragColor = vec4(camada.rgb, alfa);
}
